#!/usr/bin/env node
// Vendors packages/nz-sources from a checkout of
// https://github.com/olitreadwell/nz-open-data-connectors.
//
// npm git dependencies cannot target a subpackage inside a workspace monorepo,
// so the one package this app uses is copied here and kept in sync with this
// script. The copy is third-party code: it is not edited by hand, and it is
// regenerated by running this file.
//
// Usage:
//   node scripts/sync-connectors.mjs                       # uses ../open-data/nz-open-data-connectors
//   node scripts/sync-connectors.mjs --from /path/to/repo
//   node scripts/sync-connectors.mjs --dry-run
import {
  cpSync,
  existsSync,
  mkdirSync,
  readFileSync,
  readdirSync,
  rmSync,
  writeFileSync,
} from 'node:fs';
import { dirname, join, relative, resolve } from 'node:path';

const HERE = import.meta.dirname;
const REPO_ROOT = resolve(HERE, '..');
const VENDOR_DIR = join(REPO_ROOT, 'packages', 'nz-sources');
const UPSTREAM_PACKAGE = 'packages/nz-sources';
const PACKAGE_NAME = '@nz-open-data-connectors/nz-sources';
const args = process.argv.slice(2);
const dryRun = args.includes('--dry-run');
const fromIndex = args.indexOf('--from');
const fromDir =
  fromIndex === -1
    ? resolve(REPO_ROOT, '..', 'open-data', 'nz-open-data-connectors')
    : resolve(args[fromIndex + 1]);

// Config files are not copied: the vendored copy is linted and formatted as
// part of this app, and the upstream tsconfig extends a config that lives in
// the connectors monorepo.
/** Files copied verbatim from the upstream package. */
const SYNCED = ['README.md', 'src'];

/**
 * Copy a directory tree, skipping tests and coverage output.
 *
 * @param source - Directory to copy from
 * @param target - Directory to copy into
 */
function copyTree(source, target) {
  mkdirSync(target, { recursive: true });
  for (const entry of readdirSync(source, { withFileTypes: true })) {
    const from = join(source, entry.name);
    const to = join(target, entry.name);
    if (entry.isDirectory()) {
      // Fixture JSON backs `loadFixture()`, which this app never calls, and it
      // is 3 MB of dead weight in a repo that does not run the package's tests.
      if (entry.name === 'fixtures') continue;
      copyTree(from, to);
      continue;
    }
    if (entry.name.endsWith('.test.ts') || entry.name.endsWith('.test.tsx')) continue;
    cpSync(from, to);
    if (entry.name.endsWith('.ts')) rewriteJsSpecifiers(to);
  }
}

/**
 * Strip `.js` from relative import specifiers.
 *
 * Upstream is built with tsc under NodeNext, which requires a `.js` specifier
 * for a `.ts` file. This app consumes the source through webpack instead, and
 * webpack resolves `.ts` but does not map `.js` onto it.
 *
 * @param filePath - Vendored TypeScript file to rewrite in place
 */
function rewriteJsSpecifiers(filePath) {
  const source = readFileSync(filePath, 'utf8');
  const rewritten = source.replace(/(from\s+['"])(\.\.?\/[^'"]+)\.js(['"])/g, '$1$2$3');
  if (rewritten !== source) writeFileSync(filePath, rewritten);
}

function main() {
  const upstreamPackageDir = join(fromDir, UPSTREAM_PACKAGE);
  if (!existsSync(upstreamPackageDir)) {
    console.error(`no connectors checkout at ${upstreamPackageDir}`);
    console.error('Clone https://github.com/olitreadwell/nz-open-data-connectors or pass --from');
    process.exit(1);
  }

  const upstreamPackageJson = JSON.parse(
    readFileSync(join(upstreamPackageDir, 'package.json'), 'utf8')
  );
  if (upstreamPackageJson.name !== PACKAGE_NAME) {
    console.error(`expected ${PACKAGE_NAME}, found ${upstreamPackageJson.name}`);
    process.exit(1);
  }

  // Remove only the synced paths: pnpm's `node_modules` link for the vendored
  // package lives beside them and must survive a re-sync.
  if (!dryRun) {
    for (const entry of SYNCED) {
      rmSync(join(VENDOR_DIR, entry), { recursive: true, force: true });
    }
  }
  for (const entry of SYNCED) {
    const from = join(upstreamPackageDir, entry);
    if (!existsSync(from)) continue;
    const to = join(VENDOR_DIR, entry);
    if (dryRun) {
      console.log(`would copy ${relative(REPO_ROOT, from)} -> ${relative(REPO_ROOT, to)}`);
      continue;
    }
    if (entry === 'src') {
      copyTree(from, to);
    } else {
      mkdirSync(dirname(to), { recursive: true });
      cpSync(from, to);
    }
  }

  // The vendored copy exports TypeScript source so Next transpiles it. Its
  // dependency versions are left exactly as upstream declares them: the
  // connectors package is written against zod 3, and this app's zod 4 would
  // otherwise type-check its schemas against a different API.
  const vendoredPackageJson = {
    name: PACKAGE_NAME,
    version: upstreamPackageJson.version,
    private: true,
    type: 'module',
    main: './src/index.ts',
    types: './src/index.ts',
    exports: { '.': { types: './src/index.ts', import: './src/index.ts' } },
    dependencies: {
      'fast-xml-parser': upstreamPackageJson.dependencies['fast-xml-parser'],
      zod: upstreamPackageJson.dependencies.zod,
    },
  };

  if (dryRun) {
    console.log('would write packages/nz-sources/package.json');
    return;
  }
  writeFileSync(
    join(VENDOR_DIR, 'package.json'),
    `${JSON.stringify(vendoredPackageJson, null, 2)}\n`
  );
  console.log(`synced ${PACKAGE_NAME} from ${fromDir}`);
}

main();
